  &DefaultButton;




function dir$sysrightvoucher(p){
  this.constructor(p);
}
dir$sysrightvoucher.prototype = new DirEvent();
dir$sysrightvoucher.prototype.beforeInit = function(){
  var p = this._dir;
  if (p.options.action == 'EDIT') {
    p.field('ma_ct').disabled = true;
    p.field('username').disabled = true;
  }
}
dir$sysrightvoucher.prototype.afterInit = function(){
  var p = this._dir;
  if (p.options.action != 'NEW'){
    dir$sysrightvoucherLoadFieldGrid(p, 1);
  }
  p.options.dataChanged = true;
}
dir$sysrightvoucher.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  switch (id) {
    case 'ok':
      var g = p.grid(0), dt = g.data;
      if (!dt.findRow('[a_hidden] == 1 || [a_readonly] == 1').length) {
        $.showToast(p.msg('noChoice'));
        p.tabActive('1');
        return false;
      }
      break;
    default:
      break;
  }
  return true;
}
dir$sysrightvoucher.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
    case 'refresh':
      dir$sysrightvoucherLoadFieldGrid(p, 0);
      return false;
    default:
      break;
  }
  return true;
}
dir$sysrightvoucher.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    case 'ma_ct':
      dir$sysrightvoucherLoadFieldGrid(p, 0);
      break;
    default:
      break;
  }
}
function dir$sysrightvoucherLoadFieldGrid(p, xtype) {
  //if (p.options.wait) return;
  var time = $.userinfo.val('CommandTimeout'), controller = '@' + p.valForm('ma_ct');
  p.wait(true, controller);
  var param = { cController: controller, cFolder: "Dir" };
  $.invoke('GetDirStruct', param, p, time, function (d) {
    var k, i, item, hi, ro, f, fs, fi, dt = new DataTable(), g = p.grid(0), gdt = g.data, notrights = ['ma_nt', 'ty_gia', 'ngay_ct', 'so_ct', 'ma_nk', 'ten_nk', 'status'], grids = {}, items = {};
    if (gdt.count() > 0) {
      k = gdt.count();
      while(k--){
        items[gdt.val(k, 'tab') + '#' + gdt.val(k, 'field')] = {a_hidden: gdt.val(k, 'a_hidden'), a_readonly: gdt.val(k, 'a_readonly') }
      }
    }
    dt.addColumn(['C', 'C', 'C', 'C', 'I', 'I'], ['tab', 'tabtext', 'field', 'fieldtext', 'a_hidden', 'a_readonly']);
    if (d) {
      f = d.forms.form;
      for (k = 0; k < f.length; k++) {
        fs = f[k].fields.field;
        for (i = 0; i < fs.length; i++) {
          fi = fs[i];
          if (fi.viewType == "Grid") 
            grids[fi.name] = fi.text.lan
          else if (!fi.hidden && fi.text.lan != '' && notrights.indexOf(fi.name) == -1) {
            item = items['#' + fi.name]; 
            if (item) {hi = item.a_hidden; ro = item.a_readonly; }
            else {hi = 0; ro = 0; }
            if (xtype == 0 || hi != 0 || ro != 0) dt.addRow(['', p.msg('commonInfo'), fi.name, fi.text.lan, hi, ro]);
          }
        }
      }
      f = d.grids.grid;
      for (k = 0; k < f.length; k++) {
        fs = f[k].fields.field;
        for (i = 0; i < fs.length; i++) {
          fi = fs[i];
          if (!fi.hidden && fi.text.lan != ''){
            item = items[k + '#' + fi.name];
            if (item) {hi = item.a_hidden; ro = item.a_readonly; }
            else {hi = 0; ro = 0; }
            if (xtype == 0 || hi != 0 || ro != 0) dt.addRow([k.toString(), grids[f[k].id], fi.name, fi.text.lan.replace('%s', p.msg('FCText')), hi, ro]);
          }
        }
      }
    }

    p.appendGrid(0, dt, true);
    p.wait(false, controller);
  }, null, function () {
      p.wait(false, controller);
  })
}








select isnull(max(controller), '') as controller from dmct where ma_ct = @ma_ct






select @@fields into #@@table from @@table a where [%whereFieldKey]
[%updateRef]
select * from #@@table
drop table #@@table
if @action <> 'NEW' select username, nickname from vsysuserinfo where user_id = @user_id







select @user_id = user_id, @status = 1 from vsysuserinfo where username = @username







delete sysrightvoucher2 where [%whereFieldKey]
exec ISWIFTStoredUpdateRightVoucher @user_id, @ma_ct, @@userId, @@admin







update @@table set user_id = @user_id where user_id = @@old_user_id and ma_ct = @@old_ma_ct
update @@table set datetime2 = getdate(), user_id2 = @@userId where [%whereFieldKey]

delete sysrightvoucher2 where user_id = @@old_user_id and ma_ct = @@old_ma_ct







if exists(select 1 from @sysrightvoucher2 where a_hidden = 1 or a_readonly = 1) begin
	insert into sysrightvoucher2 select @user_id, @ma_ct, tab, field, a_hidden, a_readonly from @sysrightvoucher2 where a_hidden = 1 or a_readonly = 1
end
exec ISWIFTStoredUpdateRightVoucher @user_id, @ma_ct, @@userId, @@admin
select '' as message, is_user as [#is_user], @user_id as [#user_id] from vsysuserinfo where username = @username
